style.css:
@-moz-document domain("voz.vn") {
/* ============================================================
     voz.vn Dark
     VOZ runs XenForo 2.x, whose entire skin is driven by HSL
     design tokens stored as "H,S%,L%,A" component strings and
     consumed via hsla(var(--xf-token)). Re-authoring the core
     semantic tokens (content/border/text/link/chrome/input)
     reskins almost the whole component library at the source.
     Element-level rules below mop up the handful of hardcoded
     surfaces (header chrome, code blocks, scrollbars, the rich
     editor) and re-establish opaque dark backgrounds on every
     floating surface (menus, tooltips, sticky nav).
     ============================================================ */

  :root {
    color-scheme: dark !important;
    --xf-styleType: dark !important;
    --xf-color-adjust: -1 !important;

    /* ---- Content surfaces (light original -> dark) ---- */
    /* base page */
    --xf-pageBg:              213, 18%, 9%, 1 !important;   /* #14181d-ish, deepest */
    /* card / block / message background */
    --xf-contentBg:           214, 16%, 14%, 1 !important;  /* ~#1e242c */
    --xf-contentAltBg:        214, 15%, 17%, 1 !important;  /* ~#252b34 user cell / zebra */
    --xf-contentHighlightBg:  214, 30%, 22%, 1 !important;  /* selected / highlight row */
    --xf-contentAccentBg:     24, 45%, 20%, 1 !important;   /* orange accent, toned for dark */

    /* ---- Borders ---- */
    --xf-borderColor:         214, 14%, 22%, 1 !important;  /* ~#2d333b */
    --xf-borderColorLight:    214, 13%, 26%, 1 !important;
    --xf-borderColorHeavy:    214, 14%, 18%, 1 !important;
    --xf-borderColorFaint:    214, 14%, 20%, 1 !important;

    /* ---- Text ---- */
    --xf-textColor:           213, 30%, 92%, 1 !important;  /* #e6edf3 */
    --xf-textColorMuted:      212, 11%, 62%, 1 !important;  /* readable muted grey */
    --xf-textColorDimmed:     212, 11%, 66%, 1 !important;  /* keep dimmed legible */
    --xf-textColorEmphasized: 213, 32%, 90%, 1 !important;
    --xf-minorHeadingTextColor: 212, 14%, 72%, 1 !important;
    --xf-majorHeadingTextColor: 213, 30%, 92%, 1 !important;

    /* ---- Links / accents ---- */
    --xf-linkColor:           205, 72%, 64%, 1 !important;  /* #5fb0e6 */
    --xf-linkHoverColor:      208, 100%, 80%, 1 !important; /* #9bd4ff */
    --xf-linkUgcColor:        205, 72%, 64%, 1 !important;
    --xf-linkUgcHoverColor:   208, 100%, 80%, 1 !important;
    --xf-textColorFeature:    205, 72%, 64%, 1 !important;

    /* ---- Header / nav chrome (deep, opaque) ---- */
    --xf-chromeBg:            216, 28%, 8%, 1 !important;   /* ~#0d1117 */
    --xf-chromeTextColor:     205, 60%, 72%, 1 !important;  /* light blue nav text */
    --xf-publicHeaderAdjustColor: 0, 0%, 100%, 0.06 !important;
    --xf-subNavBg:            214, 16%, 14%, 1 !important;
    --xf-subNavTextColor:     205, 72%, 64%, 1 !important;

    /* ---- Inputs ---- */
    --xf-inputBgColor:        216, 18%, 12%, 1 !important;
    --xf-inputFocusBgColor:   216, 18%, 15%, 1 !important;
    --xf-inputTextColor:      213, 30%, 92%, 1 !important;

    /* ---- Buttons ---- */
    --xf-buttonBg:            214, 16%, 20%, 1 !important;
    --xf-buttonTextColor:     205, 72%, 70%, 1 !important;
    --xf-buttonCtaBg:         24, 70%, 52%, 1 !important;   /* VOZ orange CTA, toned */
    --xf-buttonPrimaryBg:     205, 65%, 45%, 1 !important;

    /* ---- Block headers / footers / tabs ---- */
    --xf-blockTabHeaderBg:        214, 16%, 14%, 1 !important;
    --xf-blockTabHeaderTextColor: 212, 14%, 72%, 1 !important;
    --xf-blockFooterBg:           214, 15%, 12%, 1 !important;
    --xf-blockFooterTextColor:    212, 11%, 62%, 1 !important;
    --xf-majorHeadingBg:          214, 18%, 11%, 1 !important;

    /* ---- Palette neutrals (used by misc components) ---- */
    --xf-paletteNeutral1:     214, 16%, 14%, 1 !important;
    --xf-paletteNeutral2:     212, 11%, 62%, 1 !important;
    --xf-paletteNeutral3:     213, 30%, 92%, 1 !important;
    --xf-paletteColor1:       214, 30%, 22%, 1 !important;

    /* ---- Editor (rich text reply) ---- */
    --xf-editorBg:            216, 18%, 12%, 1 !important;
    --xf-editorColor:         213, 30%, 92%, 1 !important;
    --xf-editorFocusBg:       216, 18%, 14%, 1 !important;
    --xf-editorFocusColor:    213, 30%, 92%, 1 !important;
    --xf-editorButtonColor:   212, 12%, 66%, 1 !important;
    --xf-editorButtonHoverBg: 214, 16%, 20%, 1 !important;
    --xf-editorButtonHoverColor: 213, 30%, 92%, 1 !important;
    --xf-editorButtonActiveColor: 205, 72%, 64%, 1 !important;
    --xf-editorButtonSelectedBg: 214, 16%, 22%, 1 !important;
    --xf-editorToolsOverflowBg: 216, 18%, 12%, 1 !important;

    /* ---- Selected items / inline-mod ---- */
    --xf-selectedItemBgColor:     214, 30%, 22%, 1 !important;
    --xf-selectedItemColor:       213, 30%, 92%, 1 !important;
    --xf-selectedItemBorderColor: 205, 50%, 40%, 1 !important;
    --xf-inlineModHighlightColor: 24, 45%, 20%, 1 !important;

    /* ---- Avatars / overlay mask ---- */
    --xf-avatarBg:            214, 14%, 22%, 1 !important;
    --xf-overlayMaskColor:    216, 30%, 4%, 0.7 !important;

    /* ---- Semantic colors: preserve, tune lightness for dark ---- */
    --xf-successColor:        130, 50%, 58%, 1 !important;
    --xf-successBg:           130, 30%, 14%, 1 !important;
    --xf-successFeatureColor: 130, 50%, 55%, 1 !important;
    --xf-errorColor:          5, 75%, 68%, 1 !important;
    --xf-errorBg:             5, 35%, 16%, 1 !important;
    --xf-errorFeatureColor:   5, 75%, 65%, 1 !important;
    --xf-warningColor:        38, 80%, 62%, 1 !important;
    --xf-warningBg:           38, 40%, 15%, 1 !important;
    --xf-warningFeatureColor: 38, 80%, 60%, 1 !important;
    --xf-votePositiveColor:   130, 50%, 56%, 1 !important;
    --xf-voteNegativeColor:   5, 75%, 66%, 1 !important;
    --xf-textColorAttention:  38, 80%, 62%, 1 !important;
    --xf-borderColorAttention: 38, 50%, 35%, 1 !important;

    /* ---- Read/unread node icons ---- */
    --xf-nodeIconReadColor:   212, 12%, 40%, 1 !important;
    --xf-nodeIconUnreadColor: 205, 72%, 60%, 1 !important;

    /* ---- Stars ---- */
    --xf-starFullColor:       42, 90%, 58%, 1 !important;
    --xf-starEmptyColor:      214, 12%, 30%, 1 !important;
  }

  /* ============================================================
     Base surfaces
     ============================================================ */
  html,
  body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }

  .p-pageWrapper {
    background-color: #14181d !important;
  }

  /* Soften any stray light borders the token sweep misses */
  .block-container,
  .block-row,
  .structItem,
  .message,
  .message-cell,
  .formRow,
  .inputGroup,
  hr,
  .bbCodeBlock {
    border-color: #2d333b !important;
  }

  /* Hardcoded pure-white borders the --xf-borderColor token never reaches */
  /* Rank/group chip under usernames in posts */
  .userBanner {
    border-color: #2d333b !important;
  }
  /* XenForo input addons (login "Show" password toggle, search field addons) */
  .inputGroup-text,
  .inputGroup--joined .input {
    border-color: #2d333b !important;
  }

  /* ============================================================
     Header / navigation chrome
     ============================================================ */
  .p-header,
  .p-nav,
  .p-nav-inner,
  .p-nav-list,
  .p-navSticky,
  .p-navSticky.is-sticky,
  .p-navSticky.is-sticky .p-nav {
    background-color: #0d1117 !important;
    border-color: #20262e !important;
  }

  .p-nav-opposite a,
  .p-navEl-link,
  .p-navgroup-link,
  .p-header-content a,
  .p-discovery,
  .p-discovery .bars {
    color: #c4d3e8 !important;
  }

  .p-navEl-link.p-navEl-link--splitMenu .p-navEl-splitTrigger,
  .p-navEl.is-selected > .p-navEl-link,
  .p-navEl-link:hover {
    color: #ffffff !important;
    background-color: rgba(255, 255, 255, 0.06) !important;
  }

  /* Category / block section headers (use a light gradient on the live site) */
  .block-header,
  .block-header.block-header--summary,
  .block-tabHeader,
  .block-minorTabHeader,
  .block-outer-main {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .block-header a,
  .block-header .block-header-title,
  .block-minorHeader,
  .block-minorHeader a {
    color: #c4d3e8 !important;
  }
  /* block-footer ("View more…" bar) ships the same hardcoded light XenForo
     gradient as the headers — background-color alone can't override it, kill
     the image too */
  .block-footer {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #aab4bf !important;
    border-color: #2d333b !important;
  }

  /* Content tab bars (member profile "Profile posts / Latest activity / …",
     forum tab headers): the ACTIVE tab keeps a hardcoded dark navy text
     (#273649) readable only on the light original — make it light on dark */
  .tabs-tab,
  .block-tabHeader .tabs-tab {
    color: #c4d3e8 !important;
  }
  .tabs-tab.is-active,
  .block-tabHeader .tabs-tab.is-active {
    color: #ffffff !important;
  }

  /* Section links bar under header */
  .p-sectionLinks {
    background-color: #161b22 !important;
    border-color: #20262e !important;
  }
  .p-sectionLinks-list > li > a {
    color: #c4d3e8 !important;
  }
  .p-sectionLinks-list > li.is-selected > a {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }

  /* Header search box / navgroup */
  .p-navgroup--member .p-navgroup-link--icon,
  .p-navgroup .p-navgroup-link {
    color: #c4d3e8 !important;
  }

  /* ============================================================
     Floating surfaces — must stay OPAQUE (no bleed-through)
     ============================================================ */
  .menu,
  .menu-content,
  .tooltip-content,
  .tooltip-arrow:after,
  .overlay,
  .overlay-container,
  .blockMessage,
  .autoComplete,
  .acp-menu,
  .js-headerOffsetTarget .menu {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Menu header/footer carry a hardcoded light silver gradient
     (linear-gradient(0deg, #273649, #dbe6f5)) that background-color
     alone can't override — kill the image too */
  .menu-header {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .menu-footer,
  .menu-footer-controls {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }
  .menu-row:hover,
  .menu-linkRow:hover {
    background-color: #232a33 !important;
  }
  .tooltip-content {
    box-shadow: 0 1px 6px rgba(0, 0, 0, 0.6) !important;
  }
  /* Tooltip arrow tint */
  .tooltip--basic .tooltip-arrow:before {
    border-top-color: #1c2128 !important;
  }

  /* ============================================================
     Inputs / forms / placeholders
     ============================================================ */
  .input,
  .input--date,
  select,
  textarea,
  .js-editor,
  .contentRow input,
  .formRow input {
    background-color: #11161c !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .input:focus,
  textarea:focus,
  select:focus {
    background-color: #161b22 !important;
    border-color: #3d6a96 !important;
  }
  ::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  .input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Password-strength meter (register/password change): native <meter>
     track renders bright white on dark — darken the bar, keep value colors */
  meter,
  .meterBar {
    background: #11161c !important;
    border: 1px solid #2d333b !important;
    border-radius: 6px !important;
  }
  meter::-webkit-meter-bar {
    background: #11161c !important;
    border: none !important;
    border-radius: 6px !important;
  }

  /* Buttons */
  .button,
  .buttonGroup,
  .menuTrigger {
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .button:hover {
    background-color: #2a313a !important;
    color: #ffffff !important;
  }
  .button.button--cta,
  .button--cta {
    background-image: none !important;
    background-color: #d4691e !important;
    color: #ffffff !important;
    border-color: #d4691e !important;
  }
  .button.button--cta:hover {
    background-color: #e2792c !important;
  }

  /* ============================================================
     Thread list (structItem) / forum nodes
     ============================================================ */
  /* Sort/filter bar above the thread list ships a hardcoded light-blue
     gradient (linear-gradient(0deg, #273649, #dbe6f5)) the token sweep misses */
  .block-filterBar {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }
  .structItem--thread:hover,
  .structItem.is-selected {
    background-color: #1c232c !important;
  }
  .structItem-minor,
  .structItem-parts,
  .structItem-pageJump a,
  .structItem-cell--latest .structItem-minor {
    color: #aab4bf !important;
  }
  .structItem-cell--meta dt {
    color: #8b949e !important;
  }
  .structItem-cell--meta dd {
    color: #c4cdd6 !important;
  }
  .node-extra,
  .node-meta,
  .node-statsMeta,
  .node-descriptionText,
  .nodeList .node-extra-row {
    color: #aab4bf !important;
  }

  /* ============================================================
     Messages / posts
     ============================================================ */
  .message-cell--user {
    background-color: #181d24 !important;
  }
  .message-name .username,
  .message-name a {
    color: #e6edf3 !important;
  }
  .message-userTitle,
  .message-userExtras dd,
  .message-attribution,
  .message-attribution-main a,
  .message-attribution-opposite,
  .message-attribution-opposite a {
    color: #9aa4af !important;
  }
  .bbWrapper {
    color: #c8d1da !important;
  }

  /* Quotes */
  blockquote.bbCodeBlock,
  .bbCodeBlock--quote,
  .bbCodeBlock-title,
  .bbCodeQuote-source {
    background-color: #181d24 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .bbCodeBlock-expandLink,
  .bbCodeBlock-expandLink a {
    background-color: #161b22 !important;
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Code blocks + syntax (light tokens are unreadable on dark)
     ============================================================ */
  .bbCodeCode,
  .bbCodeBlock--code,
  .bbCodeBlock--code .bbCodeBlock-content,
  pre,
  code,
  kbd,
  .code {
    background-color: #0d1117 !important;
    color: #c9d1d9 !important;
    border-color: #2d333b !important;
  }
  /* GeSHi / prettify syntax palette */
  .bbCodeCode .token.comment,
  .prettyprint .com,
  .syntaxhighlighter .comments {
    color: #8b949e !important;
  }
  .prettyprint .kwd,
  .prettyprint .tag {
    color: #ff7b72 !important;
  }
  .prettyprint .str,
  .prettyprint .atv {
    color: #a5d6ff !important;
  }
  .prettyprint .lit,
  .prettyprint .dec {
    color: #79c0ff !important;
  }
  .prettyprint .typ,
  .prettyprint .atn {
    color: #d2a8ff !important;
  }
  .prettyprint .pun,
  .prettyprint .pln {
    color: #c9d1d9 !important;
  }

  /* ============================================================
     Pagination / breadcrumbs / reactions
     ============================================================ */
  .pageNav-page a {
    background-color: #1c2128 !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .pageNav-page:hover a {
    background-color: #262d36 !important;
  }
  .pageNav-page--current a,
  .pageNav-page--current {
    background-color: #d4691e !important;
    color: #ffffff !important;
    border-color: #d4691e !important;
  }
  .p-breadcrumbs li,
  .p-breadcrumbs a,
  .breadcrumb a {
    color: #aab4bf !important;
  }
  .p-breadcrumbs:before,
  .p-description {
    color: #8b949e !important;
  }

  .reactionsBar,
  .reactionSummary,
  .message-lastEdit {
    background-color: #181d24 !important;
    color: #9aa4af !important;
    border-color: #2d333b !important;
  }

  /* Labels / tags */
  .label,
  .tagItem {
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Footer
     ============================================================ */
  .p-footer,
  .p-footer-inner,
  .p-footer-row {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #20262e !important;
  }
  .p-footer a,
  .p-footer-linkList a {
    color: #aab4bf !important;
  }

  /* ============================================================
     Misc surfaces
     ============================================================ */
  .blockLink,
  .subHeading,
  .dataList-row:hover,
  .block-outer-opposite {
    background-color: transparent !important;
  }
  .blockStatus,
  .notice {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Sticky form submit bar (login / search / post reply) + overlay
     titles also ship the light XenForo gradient — neutralize the image */
  .formSubmitRow-bar,
  .formSubmitRow,
  .menu-footer,
  .overlay-title {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .overlay-title {
    background-color: #0d1117 !important;
  }

  /* Avatar / image wrappers (avoid white tiles behind images) */
  .avatar,
  .avatarWrapper,
  .contentRow-figure,
  .structItem-iconContainer {
    background-color: transparent !important;
  }

  /* Ad wrappers ship a light/white container background that shows as grey
     bands around the (centered) ad — darken the wrapper, leave ad content */
  .ad-wrapper-sticky,
  .power_stickybanner__wrapper,
  .adsbypubpower {
    background-color: #14181d !important;
  }

  /* Scrollbar */
  * {
    scrollbar-color: #2d333b #14181d;
  }
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #14181d;
  }
  ::-webkit-scrollbar-thumb {
    background: #2d333b;
    border-radius: 6px;
    border: 2px solid #14181d;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #3a424c;
  }

  /* Text selection */
  ::selection {
    background: #2f5a86;
    color: #ffffff;
  }
}
